#!/usr/bin/env bash
# Build an .rpm for one Linux target by repackaging the compiled binary with rpmbuild.
# If rpmbuild isn't installed but docker/podman is, rpmbuild runs in a Fedora container.
# Requires (libc, libssl, ...) are generated by rpmbuild from the binary.
#
#   scripts/build-rpm.sh [TARGET]
#
# Env: PROFILE (default release), BUILDER (cargo|cross|zigbuild), DIST_DIR (default ./dist),
#      RPM_RELEASE (default 1), RPM_CONTAINER_IMAGE (default fedora:latest),
#      STATIC=1 (fully static musl binary)

source "$(dirname "${BASH_SOURCE[0]}")/packaging/common.sh"

TARGET="${1:-$(host_target)}"
[[ "${TARGET}" == *-linux-* ]] || die "rpm packages need a Linux target, got ${TARGET}"

VERSION="$(package_version)"
RELEASE="${RPM_RELEASE:-1}"
[[ "${STATIC}" == 1 ]] && RELEASE="${RELEASE}.static"
ARCH="$(rpm_arch "${TARGET}")"
CONTAINER_IMAGE="${RPM_CONTAINER_IMAGE:-fedora:latest}"

ENGINE=""
if ! command -v rpmbuild >/dev/null; then
    ENGINE="$(container_engine)"
    [[ -n "${ENGINE}" ]] || die "rpmbuild not found (dnf install rpm-build / apt install rpm), and no docker/podman to fall back on"
fi

BIN_PATH="$(build_binary "${TARGET}")"
mkdir -p "${DIST_DIR}"

STAGE="$(mktemp -d)"
trap 'rm -rf "${STAGE}"' EXIT
mkdir -p "${STAGE}"/{SOURCES,SPECS,RPMS,BUILD,BUILDROOT}
cp "${BIN_PATH}" "${ROOT_DIR}/README.md" "${ROOT_DIR}/LICENSE" "${STAGE}/SOURCES/"

cat >"${STAGE}/SPECS/${PKG_NAME}.spec" <<EOF
Name:           ${PKG_NAME}
Version:        ${VERSION}
Release:        ${RELEASE}
Summary:        $(package_field description)
License:        $(workspace_license)
URL:            $(repo_homepage)
Packager:       $(maintainer)
# TLS (rustls) verifies against the system CA store.
Requires:       ca-certificates
Source0:        ${BIN_NAME}
Source1:        README.md
Source2:        LICENSE

# Prebuilt binary: skip debuginfo extraction and post-install processing.
%global debug_package %{nil}
%global __os_install_post %{nil}

%description
Checks a GitHub-hosted Rust project for common hallmarks of low-effort
LLM-generated code, such as an old Rust edition, workspace resolver 2 and
outdated dependencies.

%prep

%build

%install
install -Dm755 %{SOURCE0} %{buildroot}%{_bindir}/${BIN_NAME}
install -Dm644 %{SOURCE1} %{buildroot}%{_docdir}/%{name}/README.md
install -Dm644 %{SOURCE2} %{buildroot}%{_licensedir}/%{name}/LICENSE

%files
%{_bindir}/${BIN_NAME}
%doc %{_docdir}/%{name}/README.md
%license %{_licensedir}/%{name}/LICENSE
EOF

# --target alone sets the package arch; a BuildArch tag would make rpmbuild refuse foreign arches.
RPMBUILD_ARGS=(-bb --quiet --target "${ARCH}" "SPECS/${PKG_NAME}.spec")

if [[ -z "${ENGINE}" ]]; then
    (cd "${STAGE}" && rpmbuild --define "_topdir ${STAGE}" "${RPMBUILD_ARGS[@]}" >&2)
else
    log "rpmbuild not installed; running it in ${CONTAINER_IMAGE} via ${ENGINE}"
    "${ENGINE}" run --rm -v "${STAGE}:/work:Z" -w /work "${CONTAINER_IMAGE}" \
        bash -c "dnf install -y -q rpm-build >/dev/null && rpmbuild --define '_topdir /work' ${RPMBUILD_ARGS[*]} && chown -R $(id -u):$(id -g) /work" >&2
fi

RPM="$(find "${STAGE}/RPMS" -name '*.rpm' -print -quit)"
[[ -n "${RPM}" ]] || die "rpmbuild produced no package"
cp "${RPM}" "${DIST_DIR}/"
OUT="${DIST_DIR}/$(basename "${RPM}")"
log "Created ${OUT} ($(du -h "${OUT}" | cut -f1))"
